            $t['x'] = $e['x'] + $f[$i][0];
            $t['y'] = $e['y'] + $f[$i][1];
            $t['step'] = $e['step'] + 1;
            if ($t['x'] < 0 || $t['y'] < 0) continue;
            if ($t['x'] >= 110 || $t['y'] >= 110) continue;
            if ($vis[$t['x']][$t['y']]) continue;
            $vis[$t['x']][$t['y']] = 1;
            $q->insert($t, -$t['step']);
        }
    }
    return -1;
}

